// === Tab: mySketch ===
// result from experiments with oscillators
// many parameters can be varied for very different results

let x = []
let y = []

let px = [], py = []

let n = 300

function setup() {
	createCanvas(800, 800)
	background(0)

	colorMode(HSB,360,100,100)

	for (let i = 0; i < n; i += 1) {
		x[i] = random(-7, 7)
		y[i] = random(-7, 7)
		px[i] = py[i] = NaN
	}

	strokeWeight(1)
	noStroke();
}

let c = 0, d = 0, e = 0

let pal = [[94, 81, 42], [90, 73, 47], [86, 69, 59], [84, 84, 71], [106, 58, 48], [105, 84, 37]]

function draw() {
	/*var context = drawingContext
	context.shadowOffsetX = 1;
	context.shadowOffsetY = 1;
	context.shadowBlur = 1; // more can be fun also
	context.shadowColor = "rgba(0, 0, 0, 0.05)";*/
	//background(0)

	translate(width/2,height/2);
	rotate(PI/4);
	translate(-width/2,-height/2);
	for (let i = 64; i-=1;){
		e += frameCount / 9000000
		for (let k = 0; k < n; k += 1) {
			let nk = (0.5 - k / n)*2

			//if (abs(nk) < 0.001) continue

			//xx = x[k]
			//x[k] = 1-y[k] + abs(x[k]/2000)/*0.000001 + *///sin(e**abs(cos(e))*nk*PI*y[k])/1000+sin(nk*PI*2)/14000
			//y[k] = xx*1.0001/* - *///cos(e**abs(sin(e))*nk*PI*x[k])/1000-cos(nk*PI*2)/14000

			xx = x[k]
			x[k] = 1-y[k] + (sin(x[k]+(0.96-y[k]/8000*e**e)))/*0.000001 + *///sin(e**abs(cos(e))*nk*PI*y[k])/1000+sin(nk*PI*2)/14000
			y[k] = 0.25+xx/(0.9995+e)/* - *///cos(e**abs(sin(e))*nk*PI*x[k])/1000-cos(nk*PI*2)/14000
			c = x[k]/24//acos(sin(x[k]/4)) / 1.5708
			d = y[k]/24//acos(sin(y[k]/4)) / 1.5708

			opx = px[k]
			opy = py[k]

			px[k] = ((floor(c * width))+width/2) //% width
			py[k] = ((floor(d * height)+height/2)) //% height

			if (isNaN(opx)) opx = px[k]
			if (isNaN(opy)) opy = py[k]

			let p = pal[floor(k/10 + frameCount/10) % pal.length]
			fill(p[0]/2, 0, abs(sin(nk+i/200))*255, 0.25)

			rect(px[k],py[k],1,1)
			//line(opx+width / 4,opy,px[k]+width / 4,py[k])
			//line(opx-width / 4,opy,px[k]-width / 4,py[k])
		}
	}

}
